332	     *
333	     * @return int the number of written pages
334	     */
335	    public function renderDocumentPages(RenderKit $services, ProjectModel $model, string $outputRoot): int
336	    {
337	        $count = 0;
338	        foreach ($model->documents as $document) {
339	            $markdown = $this->contents($model->root . '/' . $document->file);
340	            $baseMarkdown = $services->diff->baseSource($document->file);
341	            if ($markdown === null && $baseMarkdown === null) {
