343	            }
344	
345	            $this->writer->write(
346	                $outputRoot,
347	                $this->url->documentPage($document->packageName, $document->path),
348	                $this->documentPage->render($services, $document, $markdown, $baseMarkdown),
349	            );
350	            $count++;
351	        }
352	
353	        return $count;
354	    }
