356	    /**
357	     * Builds the shared render services of one generation run.
358	     *
359	     * @param ?DiffIndex $diff the comparison the site displays, if any
360	     */
361	    public function services(ProjectModel $model, ?DiffIndex $diff = null): RenderKit
362	    {
363	        return new RenderKit(
364	            $model,
365	            $this->url,
366	            new HtmlText(),
367	            new PhpHighlighter(),
368	            new MarkdownRenderer(),
369	            new TypeHtml(null, $this->url),
370	            new DoctestExtractor(),
371	            new AssertionScanner(),
372	            new DiffHtml($diff),
