391	    /**
392	     * Lists the namespaces of one package in sorted order.
393	     *
394	     * @return list<string>
395	     */
396	    public function namespacesOf(ProjectModel $model, string $packageName): array
397	    {
398	        $namespaces = [];
399	        foreach ($model->classLikes as $classLike) {
400	            if ($classLike->packageName === $packageName && !$classLike->isDev) {
401	                $namespaces[$classLike->namespace] = true;
402	            }
403	        }
404	
405	        foreach ($model->functions as $function) {
406	            if ($function->packageName === $packageName && !$function->isDev) {
407	                $namespaces[$function->namespace] = true;
408	            }
409	        }
410	
411	        ksort($namespaces);
412	
413	        return array_keys($namespaces);
414	    }
