416	    /**
417	     * Lists every unique source file of the model, tests included.
418	     *
419	     * @return list<string>
420	     */
421	    public function sourceFiles(ProjectModel $model): array
422	    {
423	        $files = [];
424	        foreach ($model->classLikes as $classLike) {
425	            $files[$classLike->file] = true;
426	        }
427	
428	        foreach ($model->functions as $function) {
429	            $files[$function->file] = true;
430	        }
431	
432	        ksort($files);
433	
434	        return array_keys($files);
435	    }
