21	/**
22	 * Loads and validates doc.yaml.
23	 */
24	final class ConfigLoader
25	{
26	    /** @var list<string> */
27	    private const KNOWN_KEYS = ['packages', 'vendor', 'vendor_dev', 'exclude', 'output', 'title', 'deptrac', 'coverage'];
28	
29	    /** @readonly */
30	    private ConfigScalarReader $scalarReader;
31	
32	    /** @readonly */
33	    private ConfigStringListReader $stringListReader;
34	
35	    /**
36	     * Creates a config loader from YAML section readers.
37	     */
38	    public function __construct(
39	        ?ConfigScalarReader $scalarReader = null,
40	        ?ConfigStringListReader $stringListReader = null,
41	    ) {
42	        $this->scalarReader = $scalarReader ?? new ConfigScalarReader();
43	        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
44	    }
45	
46	    /**
47	     * Loads and validates a DocGen YAML configuration file.
48	     *
49	     * @throws DocGenException when the file is missing, unparsable, or contains invalid values
50	     */
51	    public function load(string $path): DocGenConfig
52	    {
53	        if (!is_file($path)) {
54	            throw new DocGenException(sprintf('DocGen config not found: %s', $path));
55	        }
56	
57	        try {
58	            $data = Yaml::parseFile($path);
59	        } catch (ParseException $exception) {
60	            throw new DocGenException('Invalid doc.yaml: ' . $exception->getMessage(), 0, $exception);
61	        }
62	
63	        if (!is_array($data)) {
64	            throw new DocGenException('Invalid doc.yaml: top-level value must be a mapping.');
65	        }
66	
67	        foreach (array_keys($data) as $key) {
68	            if (!in_array((string) $key, self::KNOWN_KEYS, true)) {
69	                throw new DocGenException(sprintf('Invalid doc.yaml: top-level contains unsupported key "%s".', $key));
70	            }
71	        }
72	
73	        $root = realpath(dirname($path));
74	
75	        return new DocGenConfig(
76	            $root === false ? dirname($path) : $root,
77	            $this->stringListReader->read($data, 'packages', ['.', 'packages/*']),
78	            $this->stringListReader->read($data, 'vendor', []),
79	            $this->stringListReader->read($data, 'exclude', []),
80	            $this->scalarReader->string($data, 'output', 'build/docs'),
81	            $this->scalarReader->optionalString($data, 'title'),
82	            $this->scalarReader->optionalString($data, 'deptrac'),
83	            $this->scalarReader->optionalString($data, 'coverage'),
84	            $this->stringListReader->read($data, 'vendor_dev', []),
85	        );
86	    }
87	}
