21	/**
22	 * Parses the doc-gen command line arguments.
23	 */
24	final class DocGenCliArgumentParser
25	{
26	    /**
27	     * The long options that carry a value, inline or as the next argument.
28	     *
29	     * @var list<string>
30	     */
31	    public const VALUE_OPTIONS = ['config', 'output', 'coverage', 'memory-limit', 'jobs', 'diff', 'base', 'head'];
32	
33	    /**
34	     * Parses argument strings into a normalized option map.
35	     *
36	     * @param list<string> $argv
37	     *
38	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, help: bool, version: bool}
39	     *
40	     * @throws DocGenException when an option is unknown or lacks a value
41	     */
42	    public function parse(array $argv): array
43	    {
44	        $options = ['config' => null, 'output' => null, 'vendor' => null, 'vendorDev' => null, 'coverage' => null, 'serve' => null, 'memoryLimit' => null, 'jobs' => null, 'base' => null, 'head' => null, 'help' => false, 'version' => false];
45	        $count = count($argv);
46	        for ($index = 0; $index < $count; $index++) {
47	            $argument = $argv[$index];
48	            if ($argument === '--help' || $argument === '-h') {
49	                $options['help'] = true;
50	            } elseif ($argument === '--version' || $argument === '-V') {
51	                $options['version'] = true;
52	            } elseif ($argument === '--serve') {
53	                $options['serve'] = '127.0.0.1:8090';
54	            } elseif (str_starts_with($argument, '--serve=')) {
55	                $options['serve'] = $this->address(substr($argument, 8));
56	            } elseif ($argument === '--vendor' || str_starts_with($argument, '--vendor=')) {
57	                $options['vendor'] = $this->vendorGlobs($argument, '--vendor');
58	            } elseif ($argument === '--vendor-dev' || str_starts_with($argument, '--vendor-dev=')) {
59	                $options['vendorDev'] = $this->vendorGlobs($argument, '--vendor-dev');
60	            } elseif ($this->isValueOption($argument)) {
61	                $name = $this->optionName($argument);
62	                $options = $this->applyValueOption($options, $name, $this->take($argv, $index, $name));
63	                $index += $this->consumed($argument);
64	            } else {
65	                throw new DocGenException(sprintf('Unknown option: %s', $argument));
66	            }
67	        }
68	
69	        return $this->validated($options);
70	    }
71	
72	    /**
73	     * Reports whether an argument selects one of the value options.
74	     */
75	    public function isValueOption(string $argument): bool
76	    {
77	        foreach (self::VALUE_OPTIONS as $name) {
78	            if ($argument === '--' . $name || str_starts_with($argument, '--' . $name . '=')) {
79	                return true;
80	            }
81	        }
82	
83	        return false;
84	    }
85	
86	    /**
87	     * Returns the name of a long option, without its inline value.
88	     */
89	    public function optionName(string $argument): string
90	    {
91	        $name = substr($argument, 2);
92	        $position = strpos($name, '=');
93	
94	        return $position === false ? $name : substr($name, 0, $position);
95	    }
