97	    /**
98	     * Applies one value option to the option map.
99	     *
100	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, help: bool, version: bool} $options
101	     *
102	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, help: bool, version: bool}
103	     *
104	     * @throws DocGenException when the value of the option is malformed
105	     */
106	    public function applyValueOption(array $options, string $name, string $value): array
107	    {
108	        if ($name === 'config') {
109	            $options['config'] = $value;
110	        } elseif ($name === 'output') {
111	            $options['output'] = $value;
112	        } elseif ($name === 'coverage') {
113	            $options['coverage'] = $value;
114	        } elseif ($name === 'memory-limit') {
115	            $options['memoryLimit'] = $this->memoryLimit($value);
116	        } elseif ($name === 'jobs') {
117	            $options['jobs'] = $this->jobs($value);
118	        } elseif ($name === 'base') {
119	            $options['base'] = $value;
120	        } elseif ($name === 'head') {
