129	    /**
130	     * Splits a BASE..HEAD range into the two compared revisions.
131	     *
132	     * A range without a head compares against the working tree, which is
133	     * what a reader looking at their own uncommitted change wants.
134	     *
135	     * @param array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, help: bool, version: bool} $options
