137	     * @return array{config: ?string, output: ?string, vendor: ?list<string>, vendorDev: ?list<string>, coverage: ?string, serve: ?string, memoryLimit: ?string, jobs: ?int, base: ?string, head: ?string, help: bool, version: bool}
138	     *
139	     * @throws DocGenException when the range names no base revision
140	     */
141	    public function revisionRange(array $options, string $value): array
142	    {
143	        $parts = explode('..', $value, 2);
144	        $base = trim($parts[0]);
145	        if ($base === '') {
146	            throw new DocGenException(sprintf(
147	                'Invalid --diff range: %s. Use BASE to compare against the working tree, or BASE..HEAD to compare two revisions.',
148	                $value,
149	            ));
150	        }
151	
152	        $head = count($parts) === 2 ? trim($parts[1]) : '';
