171	            throw new DocGenException('Option --head needs a revision to compare against: add --base=REVISION, or use --diff=BASE..HEAD.');
172	        }
173	
174	        return $options;
175	    }
176	
177	    /**
178	     * Returns the inline value of a long option, or null.
179	     */
180	    public function valueOption(string $argument, string $name): ?string
181	    {
182	        $prefix = '--' . $name . '=';
183	        if (str_starts_with($argument, $prefix)) {
184	            $value = substr($argument, strlen($prefix));
185	
186	            return $value !== '' ? $value : null;
187	        }
188	
189	        return null;
190	    }
191	
192	    /**
193	     * Returns the value of an option at the current position.
194	     *
195	     * @param list<string> $argv
196	     *
197	     * @throws DocGenException when the option has no value
198	     */
199	    public function take(array $argv, int $index, string $name): string
200	    {
201	        $inline = $this->valueOption($argv[$index], $name);
202	        if ($inline !== null) {
203	            return $inline;
204	        }
205	
206	        $next = $argv[$index + 1] ?? null;
207	        if ($next === null || str_starts_with($next, '-')) {
208	            throw new DocGenException(sprintf('Option --%s requires a value.', $name));
209	        }
210	
211	        return $next;
212	    }
213	
214	    /**
215	     * Returns how many extra arguments a value option consumed.
216	     */
217	    public function consumed(string $argument): int
218	    {
219	        return str_contains($argument, '=') ? 0 : 1;
220	    }
221	
222	    /**
223	     * Returns the package name globs of a vendor option.
224	     *
225	     * The bare option without a value means every installed package, so it
226	     * expands to the match-all glob.
227	     *
228	     * @param string $argument the raw argument, such as --vendor-dev=acme/*
229	     * @param string $option the option name, such as --vendor-dev
230	     *
231	     * @return list<string>
232	     *
233	     * @throws DocGenException when the option has a value without any glob
234	     */
235	    public function vendorGlobs(string $argument, string $option): array
236	    {
237	        if ($argument === $option) {
238	            return ['*'];
239	        }
240	
241	        return $this->globList(substr($argument, strlen($option) + 1), $option);
242	    }
243	
244	    /**
245	     * Splits a comma-separated glob list.
246	     *
247	     * @param string $option the option name quoted in the error message
248	     *
249	     * @return list<string>
250	     *
251	     * @throws DocGenException when the list is empty
252	     */
253	    public function globList(string $value, string $option): array
254	    {
255	        $globs = [];
256	        foreach (explode(',', $value) as $glob) {
257	            $trimmed = trim($glob);
258	            if ($trimmed !== '') {
259	                $globs[] = $trimmed;
260	            }
261	        }
262	
263	        if ($globs === []) {
264	            throw new DocGenException(sprintf('Option %s requires at least one package name glob.', $option));
265	        }
266	
267	        return $globs;
268	    }
269	
270	    /**
271	     * Validates a memory limit value such as 512M, 1G, or -1.
272	     *
273	     * @throws DocGenException when the value is malformed
274	     */
275	    public function memoryLimit(string $value): string
276	    {
277	        if (preg_match('/^(-1|\d+[KMG]?)$/i', $value) !== 1) {
278	            throw new DocGenException(sprintf('Invalid --memory-limit value: %s. Use a byte count, a value such as 512M or 1G, or -1 for no limit.', $value));
279	        }
280	
281	        return $value;
282	    }
