3	declare(strict_types=1);
4	
5	namespace PhpAiToolkit\DocGen\Render\Signature;
6	
7	use function array_keys;
8	use function explode;
9	use function hash;
10	use function implode;
11	
12	use PhpAiToolkit\DocGen\Render\RenderKit;
13	
14	use function preg_match_all;
15	use function preg_replace;
16	use function str_contains;
17	use function strtolower;
18	
19	/**
20	 * Digests what the names on a page currently resolve to.
21	 *
22	 * A page shows more than the symbols it documents: every name it prints is
23	 * looked up, and a name that resolves to a documented symbol is printed as
24	 * a link into that symbol's page and source. A page therefore changes when
25	 * a symbol it merely names appears, disappears, or moves, which no digest
26	 * of the page's own data would notice.
27	 *
28	 * The names are read out of that data rather than tracked one lookup at a
29	 * time, and every form a name could resolve to is digested, so a page
30	 * depends on at least everything it can read and never on less.
31	 */
32	final class SymbolReferenceScanner
33	{
34	    /**
35	     * Matches every name-shaped run of characters, qualified or not.
36	     */
37	    public const NAME_PATTERN = '/[A-Za-z_\x80-\xff][A-Za-z0-9_\x80-\xff]*(?:\\\\[A-Za-z_\x80-\xff][A-Za-z0-9_\x80-\xff]*)*/';
38	
39	    /**
40	     * Matches the class names that PHP's serialization writes itself.
41	     */
42	    public const SERIALIZED_CLASS_PATTERN = '/[OCE]:\d+:"[^"]*"/';
43	
44	    /**
45	     * Digest of a name that resolves to no documented symbol.
46	     */
47	    public const UNRESOLVED = '-';
48	
49	    private ?RenderKit $run = null;
50	
51	    /** @var array<string, string> */
52	    private array $digests = [];
53	
54	    /**
55	     * Digests every symbol the names in one blob resolve to.
56	     *
57	     * @param string $blob the data the page is rendered from
58	     * @param string $namespace the namespace names on the page are written in
59	     * @param array<string, string> $useMap the imports names on the page are written under
60	     */
61	    public function digest(RenderKit $services, SourceDigestIndex $sources, string $blob, string $namespace, array $useMap): string
62	    {
63	        $parts = [];
64	        foreach ($this->names($blob, $namespace, $useMap) as $name) {
65	            $parts[] = $name . "\0" . $this->symbolDigest($services, $sources, $name);
66	        }
67	
68	        return hash('sha256', implode("\n", $parts));
69	    }
70	
71	    /**
72	     * Lists every name one blob could have a symbol looked up under.
73	     *
74	     * A written name resolves through the imports of its file, through the
75	     * namespace it is written in, or as it stands, so all three readings
76	     * are listed: which one a renderer takes is its own business, and the
77	     * ones it does not take resolve to nothing.
78	     *
79	     * The names keep the order the blob wrote them in, which is an order
80	     * of the data rather than of this scan, so the digest of a page that
81	     * did not change does not change either.
82	     *
83	     * @param array<string, string> $useMap
84	     *
85	     * @return list<string>
86	     */
87	    public function names(string $blob, string $namespace, array $useMap): array
88	    {
89	        $matches = [];
90	        preg_match_all(self::NAME_PATTERN, (string) preg_replace(self::SERIALIZED_CLASS_PATTERN, ' ', $blob), $matches);
91	        $names = array_fill_keys($matches[0], true);
92	        foreach (array_keys($names) as $written) {
93	            if ($namespace !== '') {
94	                $names[$namespace . '\\' . $written] = true;
95	            }
96	
97	            $imported = $this->imported($written, $useMap);
98	            if ($imported !== null) {
99	                $names[$imported] = true;
100	            }
101	        }
102	
103	        return array_keys($names);
104	    }
105	
106	    /**
107	     * Resolves one written name through the imports of its file.
108	     *
109	     * @param array<string, string> $useMap
110	     */
111	    public function imported(string $written, array $useMap): ?string
112	    {
113	        $first = $written;
114	        $rest = '';
115	        if (str_contains($written, '\\')) {
116	            [$first, $rest] = explode('\\', $written, 2);
117	            $rest = '\\' . $rest;
118	        }
119	
120	        $imported = $useMap[strtolower($first)] ?? null;
121	
122	        return $imported === null ? null : $imported . $rest;
123	    }
124	
125	    /**
126	     * Digests the symbol one name resolves to, or its absence.
127	     *
128	     * The digest of a symbol is the digest of the file it is declared in,
129	     * because that file decides everything the symbol documents; the
130	     * package and the kind of source it was found in decide the rest.
131	     *
132	     * What a name resolves to holds for the whole run, and the pages of a
133	     * project name the same symbols over and over, so every name is
134	     * resolved once per run rather than once per page.
135	     */
136	    public function symbolDigest(RenderKit $services, SourceDigestIndex $sources, string $name): string
137	    {
138	        if ($this->run !== $services) {
139	            $this->run = $services;
140	            $this->digests = [];
141	        }
142	
143	        return $this->digests[$name] ??= $this->resolved($services, $sources, $name);
144	    }
145	
146	    /**
147	     * Resolves one name to the digest of the symbol it names.
148	     */
149	    public function resolved(RenderKit $services, SourceDigestIndex $sources, string $name): string
150	    {
151	        $root = $services->model->root;
152	        $classLike = $services->model->symbolTable->classLike($name);
153	        if ($classLike !== null) {
154	            return 'class-like|' . $sources->of($root, $classLike->file) . '|' . $classLike->packageName . '|' . ($classLike->isDev ? 'dev' : 'src');
155	        }
156	
157	        $function = $services->model->symbolTable->functionNamed($name);
158	        if ($function !== null) {
159	            return 'function|' . $sources->of($root, $function->file) . '|' . $function->packageName . '|' . ($function->isDev ? 'dev' : 'src');
160	        }
161	
162	        return self::UNRESOLVED;
163	    }
164	}

