20	/**
21	 * Remembers the parsed symbols of source files between runs.
22	 *
23	 * Every file is remembered on its own, under a name that is the file's own
24	 * content: a run reads back exactly the files it documents, and the worker
25	 * that would have parsed a file is the worker that reads it instead. That
26	 * is what keeps a cached run as parallel as an uncached one, which a
27	 * single cache file for the whole project could not be.
28	 *
29	 * Entries nobody read for a while are dropped, so a cache that outlived
30	 * the branches it was filled from does not grow without end.
31	 */
32	final class ParseCache
33	{
34	    /**
35	     * How long an unread entry is kept before it is dropped, in seconds.
36	     */
37	    public const RETENTION = 604800;
38	
39	    /**
40	     * How old an entry has to be before reading it marks it as read.
41	     */
42	    public const TOUCH_AFTER = 86400;
43	
44	    /**
45	     * Name of the entry directory below the cache directory.
46	     */
47	    public const DIRECTORY = 'sources';
48	
49	    /** @readonly */
50	    private string $directory;
51	
52	    /** @readonly */
53	    private CacheStore $store;
54	
55	    private int $reused = 0;
56	
57	    private int $parsed = 0;
58	
59	    /**
60	     * Creates a parse cache below one cache directory.
61	     */
62	    public function __construct(string $directory, ?CacheStore $store = null)
63	    {
64	        $this->directory = $directory . '/' . self::DIRECTORY;
65	        $this->store = $store ?? new CacheStore();
66	    }
67	
68	    /**
69	     * Returns the file one entry is kept in.
70	     *
71	     * Entries are spread over a level of directories named after the start
72	     * of their key, because a directory of one entry per source file of a
73	     * documented dependency tree is a directory nothing enjoys reading.
74	     */
75	    public function path(string $key): string
76	    {
77	        return $this->directory . '/' . substr($key, 0, 2) . '/' . $key . '.cache';
78	    }
79	
80	    /**
81	     * Returns what is remembered about one file, or null.
82	     *
83	     * @return ?array{symbols: FileSymbols|string, usages: list<Usage>}
84	     */
85	    public function find(string $key): ?array
86	    {
87	        $path = $this->path($key);
88	        $entry = $this->entry($this->store->read($path));
89	        if ($entry !== null) {
90	            $this->keep($path);
91	        }
92	
93	        return $entry;
94	    }
95	
96	    /**
97	     * Remembers what one file was parsed into.
98	     *
99	     * @param FileSymbols|string $symbols the symbols of the file, or the warning it produced
100	     * @param list<Usage> $usages the references the file makes
101	     */
102	    public function remember(string $key, $symbols, array $usages): void
103	    {
104	        $this->store->write($this->path($key), ['symbols' => $symbols, 'usages' => $usages]);
105	    }
106	
107	    /**
108	     * Counts one documented file as read back or as parsed.
109	     */
110	    public function counted(bool $reused): void
111	    {
112	        if ($reused) {
113	            $this->reused++;
114	        } else {
115	            $this->parsed++;
116	        }
117	    }
118	
119	    /**
120	     * Marks one entry as read, at most once a day.
121	     *
122	     * An entry is kept for as long as it is used, which is what its age
123	     * says; writing that age on every read would cost more than the entry.
124	     */
125	    public function keep(string $path): void
126	    {
127	        $modified = @filemtime($path);
128	        if ($modified !== false && $modified < time() - self::TOUCH_AFTER) {
129	            @touch($path);
130	        }
131	    }
132	
133	    /**
134	     * Drops the entries no run has read for a while.
135	     */
136	    public function prune(): void
137	    {
138	        if (!is_dir($this->directory)) {
139	            return;
140	        }
141	
142	        $oldest = time() - self::RETENTION;
143	        $shards = scandir($this->directory);
144	        if ($shards === false) {
145	            return;
146	        }
147	
148	        foreach ($shards as $shard) {
149	            if ($shard !== '.' && $shard !== '..') {
150	                $this->pruneShard($this->directory . '/' . $shard, $oldest);
151	            }
152	        }
153	    }
154	
155	    /**
156	     * Drops the entries of one shard that are older than one moment.
157	     */
158	    public function pruneShard(string $directory, int $oldest): void
159	    {
160	        if (!is_dir($directory)) {
161	            return;
162	        }
163	
164	        $entries = scandir($directory);
165	        if ($entries === false) {
166	            return;
167	        }
168	
169	        foreach ($entries as $entry) {
170	            if ($entry === '.' || $entry === '..') {
171	                continue;
172	            }
173	
174	            $path = $directory . '/' . $entry;
175	            $modified = @filemtime($path);
176	            if ($modified !== false && $modified < $oldest) {
177	                @unlink($path);
178	            }
179	        }
180	    }
181	
182	    /**
183	     * Reads one stored entry as the parse result it must be.
184	     *
185	     * Entries come from files that any tool could have written over, so an
186	     * entry that is not a whole parse result is no entry at all.
187	     *
188	     * @param array<mixed> $entry
189	     *
190	     * @return ?array{symbols: FileSymbols|string, usages: list<Usage>}
191	     */
192	    public function entry(array $entry): ?array
193	    {
194	        if (!isset($entry['symbols'], $entry['usages'])) {
195	            return null;
196	        }
197	
198	        $symbols = $entry['symbols'];
199	        $usages = $entry['usages'];
200	        if (!is_array($usages) || (!is_string($symbols) && !$symbols instanceof FileSymbols)) {
201	            return null;
202	        }
203	
204	        $references = [];
205	        foreach ($usages as $usage) {
206	            if (!$usage instanceof Usage) {
207	                return null;
208	            }
209	
210	            $references[] = $usage;
211	        }
212	
213	        return ['symbols' => $symbols, 'usages' => $references];
214	    }
215	
216	    /**
217	     * Returns how many files this run took from the cache.
218	     */
219	    public function reused(): int
220	    {
221	        return $this->reused;
222	    }
223	
224	    /**
225	     * Returns how many files this run had to parse.
226	     */
227	    public function parsed(): int
228	    {
229	        return $this->parsed;
230	    }
231	}

