49	                $options['help'] = true;
50	            } elseif ($argument === '--version' || $argument === '-V') {
51	                $options['version'] = true;
52	            } elseif ($argument === '--serve') {
53	                $options['serve'] = '127.0.0.1:8090';
54	            } elseif (str_starts_with($argument, '--serve=')) {
55	                $options['serve'] = $this->address(substr($argument, 8));
56	            } elseif ($argument === '--vendor' || str_starts_with($argument, '--vendor=')) {
57	                $options['vendor'] = $this->vendorGlobs($argument, '--vendor');
58	            } elseif ($argument === '--vendor-dev' || str_starts_with($argument, '--vendor-dev=')) {
59	                $options['vendorDev'] = $this->vendorGlobs($argument, '--vendor-dev');
60	            } elseif ($this->isValueOption($argument)) {
